import { Component, computed, inject, input } from '@angular/core';
import { Claim } from './claims.service';
import { STATUSES } from './summary';
import { FigurePipe } from '../../core/figure.pipe';
import { Session } from '../../core/session';

// The sheet's header, shown at all times: how many people are on the sheet (retired ones
// included), how many claims are in each status (as the summary counts them), and the sheet's
// due-total and overdue-total (as its totals show them), and the signed-in user's own due-total and
// overdue-total when a person on the sheet has their name or alias, and their crew total (the due-totals
// of the crews that person leads, added up) when they lead one, and how many REVIEW claims are
// assigned to the signed-in user to review.
@Component({
  selector: 'app-header',
  imports: [FigurePipe],
  template: `
    <header aria-label="Sheet counters" data-testid="header">
      <dl>
        <div>
          <dt>People</dt>
          <dd data-testid="header-people-count">{{ (peopleCount()) | figure }}</dd>
        </div>
        @for (s of byStatus(); track s.status) {
          <div>
            <dt>{{ (s.status) | figure }}</dt>
            <dd [attr.data-testid]="'header-claims-' + s.status + '-count'">{{ (s.count) | figure }}</dd>
          </div>
        }
        <div>
          <dt>Due</dt>
          <dd data-testid="header-due-total">{{ (dueTotal()) | figure }}</dd>
        </div>
        <div>
          <dt>Overdue</dt>
          <dd data-testid="header-overdue-total">{{ (overdueTotal()) | figure }}</dd>
        </div>
        <div>
          <dt>My due</dt>
          <dd data-testid="my-due-total">{{ (myDueTotal()) | figure }}</dd>
        </div>
        <div>
          <dt>My overdue</dt>
          <dd data-testid="my-overdue-total">{{ (myOverdueTotal()) | figure }}</dd>
        </div>
        <div>
          <dt>My crew due</dt>
          <dd data-testid="my-crew-due-total">{{ (myCrewDueTotal()) | figure }}</dd>
        </div>
        <div>
          <dt>My reviews</dt>
          <dd data-testid="my-reviews-count">{{ (myReviewsCount()) | figure }}</dd>
        </div>
        <div>
          <dt>Watched due</dt>
          <dd data-testid="watched-due-total">{{ (watchedDueTotal()) | figure }}</dd>
        </div>
      </dl>
    </header>
  `,
  styles: `
    dl {
      display: flex;
      flex-wrap: wrap;
      gap: 1.5rem;
      margin: 0 0 1rem;
    }
    dt {
      font-weight: bold;
    }
    dd {
      margin: 0;
    }
  `,
})
export class Header {
  private readonly session = inject(Session);
  /** How many people are on the sheet, retired ones included. */
  readonly peopleCount = input.required<number>();
  /** The sheet's claims. */
  readonly claims = input.required<Claim[]>();
  /** The sheet's due-total, with two decimals. */
  readonly dueTotal = input.required<string>();
  /** The sheet's overdue-total, with two decimals. */
  readonly overdueTotal = input.required<string>();
  /** The signed-in user's own due-total (of the person with their name or alias); blank when none. */
  readonly myDueTotal = input.required<string>();
  /** The signed-in user's own overdue-total; blank when there is no such person. */
  readonly myOverdueTotal = input.required<string>();
  /** The due-totals of the crews the signed-in user's person leads, added up; blank when they lead none. */
  readonly myCrewDueTotal = input.required<string>();
  /** The due-totals of the people the signed-in user watches, added up; 0.00 when they watch no one. */
  readonly watchedDueTotal = input.required<string>();

  /** How many REVIEW claims are assigned to the signed-in user to review. */
  protected readonly myReviewsCount = computed(() => {
    const user = this.session.user();
    return this.claims().filter((c) => c.status === 'REVIEW' && user !== null && c.reviewAssigned === user).length;
  });

  protected readonly byStatus = computed(() =>
    STATUSES.map((status) => ({
      status,
      count: this.claims().filter((c) => c.status === status).length,
    })),
  );
}
              }
              <th scope="col">Claims</th>
              <th scope="col">Plans</th>
              <th scope="col"><span class="visually-hidden">Actions</span></th>
            </tr>
          </thead>
          <tbody>
            @for (p of shownPeople(); track p.id) {
              <tr [attr.data-testid]="'person-row-' + p.id">
                <td>
                  <input
                    type="checkbox"
                    data-testid="person-select"
                    [attr.aria-label]="'Select ' + p.name"
                    [checked]="selectedPeople().has(p.id)"
                    (change)="selectPerson(p.id, checked($event))"
                  />
                </td>
                <td data-testid="person-name">{{ (withGrade(p.name, gradeNow(p))) | figure }}</td>
                <td data-testid="person-grade">{{ (gradeNow(p)) | figure }}</td>
                @if (shows('terms')) {
                  <td data-testid="person-terms">{{ (p.terms ?? '') | figure }}</td>
                }
                @if (shows('contact')) {
                  <td data-testid="person-contact">{{ (p.contact ?? '') | figure }}</td>
                }
                <td data-testid="person-tags">{{ (p.tags.join(', ')) | figure }}</td>
                @if (shows('aliases')) {
                  <td data-testid="person-aliases">{{ (p.aliases.join(', ')) | figure }}</td>
                }
                <td data-testid="person-clashing">{{ (p.clashing ? 'yes' : 'no') | figure }}</td>
                <td data-testid="person-origin">{{ (p.origin ?? '') | figure }}</td>
                @if (shows('claimed')) {
                  <td data-testid="person-claimed">{{ (claimedOf(p)) | figure }}</td>
                }
                @if (shows('due-total')) {
                  <td data-testid="person-due-total">{{ (dueTotalOf(p) ?? 'n/a') | figure }}</td>
                }
                @let split = claimedSplitOf(p);
                <td data-testid="person-settled-total">{{ (money(split.settled)) | figure }}</td>
                <td data-testid="person-open-total">{{ (money(split.open)) | figure }}</td>
                @for (pd of periods(); track pd.id) {
                  <td [attr.data-testid]="'person-period-' + pd.name + '-due-total'">{{ (money(personPeriodCents().get(p.id)?.[pd.name] ?? 0)) | figure }}</td>
                  <td [attr.data-testid]="'person-period-' + pd.name + '-carried'">{{ (money(personCarriedCents().get(p.id)?.[pd.name] ?? 0)) | figure }}</td>
                }
                @if (shows('excess')) {
                  <td data-testid="person-excess">{{ (excessOf(p)) | figure }}</td>
                }
                <td data-testid="person-cut-total">{{ (money(cutCents().get(p.id) ?? 0)) | figure }}</td>
                @if (shows('overdue-count')) {
                  <td data-testid="person-overdue-count">{{ (overdueOf(p).count) | figure }}</td>
                }
                <td data-testid="person-score">{{ (scoreOf(p)) | figure }}</td>
                <td data-testid="person-band">{{ (bandOf(p)) | figure }}</td>
                @if (shows('overdue-total')) {
                  <td data-testid="person-overdue-total">{{ (money(overdueOf(p).cents)) | figure }}</td>
                }
                @let aged = agedOf(p);
                <td data-testid="person-aged-0-30">{{ (money(aged[0])) | figure }}</td>
                <td data-testid="person-aged-31-60">{{ (money(aged[1])) | figure }}</td>
                <td data-testid="person-aged-61">{{ (money(aged[2])) | figure }}</td>
                @if (shows('statement-count')) {
                  <td data-testid="person-statement-count">{{ (statementsOf(p.id).length) | figure }}</td>
                }
                @if (shows('stated-total')) {
                  <td data-testid="person-stated-total">{{ (lastStatementOf(p.id)?.dueTotal ?? '') | figure }}</td>
                }
                @if (shows('statement-date')) {
                  <td data-testid="person-statement-date">{{ (lastStatementOf(p.id)?.date ?? '') | figure }}</td>
                }
                @if (shows('retired')) {
                  <td data-testid="person-retired">{{ (p.retired ? 'yes' : 'no') | figure }}</td>
                }
                <td data-testid="person-retired-from">{{ (p.retiredFrom ?? '') | figure }}</td>
                <td data-testid="person-flag-shown">{{ (p.flag ?? '') | figure }}</td>
                <td data-testid="person-approver">{{ (p.approver ?? '') | figure }}</td>
                @if (shows('hold')) {
                  <td data-testid="person-hold">{{ (p.held ? 'yes' : 'no') | figure }}</td>
                }
                <td data-testid="person-active">{{ (isActive(p) ? 'yes' : 'no') | figure }}</td>
                <td data-testid="person-watched">{{ (watched().has(p.id) ? 'yes' : 'no') | figure }}</td>

  /** Download the person's statement as a CSV file: each claim of theirs their last statement bound,
   *  oldest first, with number, date, amount, the bound figure as the claim shows it, and status. */
  protected async exportStatement(person: Person): Promise<void> {
    if (!(await this.readDone())) return;
    const last = this.lastStatementOf(person.id);
    const lines = [['number', 'date', 'amount', 'figure', 'status']];
    for (const c of [...this.claimsOf(person.id)].reverse()) {
      if (last === null || !c.stated || c.statedBy !== last.id) continue;
      const figure = claimShownCents(c, this.rates(), person.grades, this.floors(), this.lateness(), this.roundingOf(person.id));
      lines.push([c.number ?? '', c.date, c.amount, figure === null ? 'n/a' : money(figure), c.status]);
    }
    this.downloadCsv('statement.csv', lines);
  }

  /** Download the person's row as a CSV file: one line per cell, with the value as the row shows it. */
  protected async exportPerson(person: Person): Promise<void> {
    if (!(await this.readDone())) return;
    const p = this.people().find((q) => q.id === person.id) ?? person;
    const cells: [string, string | number][] = [
      ['person-name', withGrade(p.name, this.gradeNow(p))],
      ['person-grade', this.gradeNow(p)],
      ['person-claimed', this.claimedOf(p)],
      ['person-due-total', this.dueTotalOf(p) ?? 'n/a'],
      ['person-statement-count', this.statementsOf(p.id).length],
      ['person-overdue-total', money(this.overdueOf(p).cents)],
      ['person-hold', p.held ? 'yes' : 'no'],
      ['person-retired', p.retired ? 'yes' : 'no'],
      ['person-aliases', p.aliases.join(', ')],
      ['person-score', this.scoreOf(p)],
    ];
    const lines = [['cell', 'value'], ...cells.map(([cell, v]) => [cell, String(this.figure.transform(v))])];
    this.downloadCsv('person.csv', lines);
  }

  /** Wait for the sheet's last read, as of the date set when one is, to be shown, so an export taken
   *  just after a load shows what it read; false when no sheet is loaded. */
